'use client'

import { useActionState } from 'react'

async function submitContactMessage(prevState: { success: boolean; message: string }, formData: FormData) {
  'use server'

  const name = formData.get('name') as string
  const email = formData.get('email') as string
  const message = formData.get('message') as string

  // Validation: Check that all fields are provided
  if (!name || !name.trim()) {
    return { success: false, message: 'Name is required' }
  }

  if (!email || !email.trim()) {
    return { success: false, message: 'Email is required' }
  }

  if (!message || !message.trim()) {
    return { success: false, message: 'Message is required' }
  }

  // Email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!emailRegex.test(email)) {
    return { success: false, message: 'Please provide a valid email address' }
  }

  // Simulate saving the contact message
  console.log('Contact message submitted:', { name, email, message })

  return { success: true, message: 'Thank you for your message! We will get back to you soon.' }
}

export default function ContactForm() {
  const [state, formAction, pending] = useActionState(submitContactMessage, {
    success: false,
    message: ''
  })

  return (
    <div>
      <h2>Contact Us</h2>

      {state.message && (
        <p style={{ color: state.success ? 'green' : 'red' }}>
          {state.message}
        </p>
      )}

      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input
            id="name"
            name="name"
            type="text"
            placeholder="Your name"
            required
          />
        </div>

        <div>
          <label htmlFor="email">Email</label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="your@email.com"
            required
          />
        </div>

        <div>
          <label htmlFor="message">Message</label>
          <textarea
            id="message"
            name="message"
            placeholder="Your message..."
            rows={5}
            required
          />
        </div>

        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  )
}

